import numpy as np

def select_next_node(cur_truck_pos, depot_pos, all_truck_pos, unvisited_customers):
    best_node = 0
    best_score = float('inf')
    alpha = 0.5  # balancing parameter

    for i, customer in enumerate(unvisited_customers):
        dist_cur = np.linalg.norm(customer - cur_truck_pos)
        # Count how many other trucks are closer to this customer than the current truck
        count_close = 0
        for other_pos in all_truck_pos:
            # Avoid counting the current truck itself (compare arrays)
            if not np.array_equal(other_pos, cur_truck_pos):
                dist_other = np.linalg.norm(customer - other_pos)
                if dist_other < dist_cur:
                    count_close += 1
        score = dist_cur * (1 + alpha * count_close)
        if score < best_score:
            best_score = score
            best_node = i

    return best_node
